<!DOCTYPE html>
<html lang="pt-BR">
<head>
<meta charset="UTF-8">
<title>Diario Official — 1 de Abril de 1900</title>
<style>
    body{
        background:#d9d2c0;
        margin:0;
        padding:20px 0;
    }
    .folha{
        width:1050px;
        margin:0 auto;
        background:#efe9da;
        padding:28px 34px 40px 34px;
        font-family:"Times New Roman", Times, serif;
        color:#1a1a1a;
    }
    .cabecalho{
        display:flex;
        justify-content:space-between;
        align-items:flex-end;
        font-size:15px;
        letter-spacing:.5px;
        padding:0 6px 3px 6px;
    }
    .cabecalho .titulo{
        font-size:17px;
        letter-spacing:2px;
        font-weight:bold;
    }
    .cabecalho .pagina{
        font-weight:bold;
    }
    .regua{
        border-top:2px solid #1a1a1a;
        border-bottom:1px solid #1a1a1a;
        height:2px;
        margin-bottom:14px;
    }
    .colunas{
        display:flex;
        column-gap:0;
    }
    .col{
        width:33.33%;
        padding:0 12px;
        font-size:12.5px;
        line-height:1.32;
        text-align:justify;
        hyphens:auto;
    }
    .col + .col{
        border-left:1px solid #1a1a1a;
    }
