        margin:0;
        text-indent:1.6em;
    }
    .semrecuo{ text-indent:0; }
    h2.sub{
        text-align:center;
        font-size:13px;
        font-weight:normal;
        letter-spacing:1px;
        margin:10px 0 4px 0;
    }
    h3.sec{
        text-align:center;
        font-size:12px;
        font-weight:normal;
        font-variant:small-caps;
        margin:6px 0 4px 0;
    }
    .italico-centro{
        text-align:center;
        font-style:italic;
        margin:7px 0 4px 0;
    }
    table.tab{
        width:100%;
        border-collapse:collapse;
        font-size:12.5px;
        margin:2px 0 6px 0;
    }
    table.tab td{
        padding:1px 2px;
        white-space:nowrap;
    }
    table.tab td.dir{ text-align:right; }
    table.tab th{
        font-style:italic;
        font-weight:normal;
